-- Simple inventory app schema: sites and devices
-- PostgreSQL compatible

CREATE TABLE IF NOT EXISTS sites (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR({{int:204:306}}) NOT NULL UNIQUE,
    address TEXT,
    city VARCHAR({{int:204:306}}),
    country VARCHAR({{int:80:120}}),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS devices (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    site_id UUID NOT NULL REFERENCES sites(id) ON DELETE CASCADE,
    name VARCHAR({{int:204:306}}) NOT NULL,
    serial_number VARCHAR({{int:204:306}}) UNIQUE,
    device_type VARCHAR({{int:80:120}}) NOT NULL,
    status VARCHAR({{int:40:60}}) NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive','maintenance','retired')),
    model VARCHAR({{int:204:306}}),
    vendor VARCHAR({{int:204:306}}),
    purchase_date DATE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_devices_site_id ON devices(site_id);
CREATE INDEX idx_devices_status ON devices(status);
CREATE INDEX idx_devices_serial_number ON devices(serial_number);

-- Trigger to update updated_at
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS sites_updated_at ON sites;
CREATE TRIGGER sites_updated_at
BEFORE UPDATE ON sites
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS devices_updated_at ON devices;
CREATE TRIGGER devices_updated_at
BEFORE UPDATE ON devices
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

package inventory

import (
    "context"
    "database/sql"
    "errors"
    "time"
)

var (
    ErrNotFound = errors.New("record not found")
)

type Site struct {
    ID        string     `db:"id"`
    Name      string     `db:"name"`
    Address   *string    `db:"address"`
    City      *string    `db:"city"`
    Country   *string    `db:"country"`
    CreatedAt time.Time  `db:"created_at"`
    UpdatedAt time.Time  `db:"updated_at"`
}

type Device struct {
    ID           string     `db:"id"`
    SiteID       string     `db:"site_id"`
    Name         string     `db:"name"`
    SerialNumber *string    `db:"serial_number"`
    DeviceType   string     `db:"device_type"`
    Status       string     `db:"status"`
    Model        *string    `db:"model"`
    Vendor       *string    `db:"vendor"`
    PurchaseDate *time.Time `db:"purchase_date"`
    CreatedAt    time.Time  `db:"created_at"`
    UpdatedAt    time.Time  `db:"updated_at"`
}

type SiteWithDevices struct {
    Site
    Devices []Device
}

type Repo struct {
    db *sql.DB
}

func NewRepo(db *sql.DB) *Repo {
    return &Repo{db: db}
}

// Sites

func (r *Repo) CreateSite(ctx context.Context, s Site) (Site, error) {
    query := `INSERT INTO sites (name, address, city, country)
              VALUES ($1,$2,$3,$4)
              RETURNING id, name, address, city, country, created_at, updated_at`
    err := r.db.QueryRowContext(ctx, query, s.Name, s.Address, s.City, s.Country).
        Scan(&s.ID, &s.Name, &s.Address, &s.City, &s.Country, &s.CreatedAt, &s.UpdatedAt)
    return s, err
}

func (r *Repo) GetSite(ctx context.Context, id string) (Site, error) {
    var s Site
    err := r.db.QueryRowContext(ctx,
        `SELECT id, name, address, city, country, created_at, updated_at FROM sites WHERE id=$1`,
        id).Scan(&s.ID, &s.Name, &s.Address, &s.City, &s.Country, &s.CreatedAt, &s.UpdatedAt)
    if err == sql.ErrNoRows {
        return Site{}, ErrNotFound
    }
    return s, err
}

func (r *Repo) ListSites(ctx context.Context) ([]Site, error) {
    rows, err := r.db.QueryContext(ctx,
        `SELECT id, name, address, city, country, created_at, updated_at FROM sites ORDER BY name`)
    if err != nil {
        return nil, err
    }
    defer rows.Close()
    var out []Site
    for rows.Next() {
        var s Site
        if err := rows.Scan(&s.ID, &s.Name, &s.Address, &s.City, &s.Country, &s.CreatedAt, &s.UpdatedAt); err != nil {
            return nil, err
        }
        out = append(out, s)
    }
    return out, rows.Err()
}

func (r *Repo) UpdateSite(ctx context.Context, s Site) error {
    res, err := r.db.ExecContext(ctx,
        `UPDATE sites SET name=$1, address=$2, city=$3, country=$4, updated_at=NOW() WHERE id=$5`,
        s.Name, s.Address, s.City, s.Country, s.ID)
    if err != nil {
        return err
    }
    n, _ := res.RowsAffected()
    if n == 0 {
        return ErrNotFound
    }
    return nil
}

func (r *Repo) DeleteSite(ctx context.Context, id string) error {
    res, err := r.db.ExecContext(ctx, `DELETE FROM sites WHERE id=$1`, id)
    if err != nil {
        return err
    }
    n, _ := res.RowsAffected()
    if n == 0 {
        return ErrNotFound
    }
    return nil
}

// Devices

func (r *Repo) CreateDevice(ctx context.Context, d Device) (Device, error) {
    query := `INSERT INTO devices (site_id, name, serial_number, device_type, status, model, vendor, purchase_date)
              VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
              RETURNING id, site_id, name, serial_number, device_type, status, model, vendor, purchase_date, created_at, updated_at`
    err := r.db.QueryRowContext(ctx, query,
        d.SiteID, d.Name, d.SerialNumber, d.DeviceType, d.Status, d.Model, d.Vendor, d.PurchaseDate).
        Scan(&d.ID, &d.SiteID, &d.Name, &d.SerialNumber, &d.DeviceType, &d.Status, &d.Model, &d.Vendor, &d.PurchaseDate, &d.CreatedAt, &d.UpdatedAt)
    return d, err
}

func (r *Repo) GetDevice(ctx context.Context, id string) (Device, error) {
    var d Device
    err := r.db.QueryRowContext(ctx,
        `SELECT id, site_id, name, serial_number, device_type, status, model, vendor, purchase_date, created_at, updated_at FROM devices WHERE id=$1`,
        id).Scan(&d.ID, &d.SiteID, &d.Name, &d.SerialNumber, &d.DeviceType, &d.Status, &d.Model, &d.Vendor, &d.PurchaseDate, &d.CreatedAt, &d.UpdatedAt)
    if err == sql.ErrNoRows {
        return Device{}, ErrNotFound
    }
    return d, err
}

func (r *Repo) ListDevicesBySite(ctx context.Context, siteID string) ([]Device, error) {
    rows, err := r.db.QueryContext(ctx,
        `SELECT id, site_id, name, serial_number, device_type, status, model, vendor, purchase_date, created_at, updated_at
         FROM devices WHERE site_id=$1 ORDER BY name`, siteID)
    if err != nil {
        return nil, err
    }
    defer rows.Close()
    var out []Device
    for rows.Next() {
        var d Device
        if err := rows.Scan(&d.ID, &d.SiteID, &d.Name, &d.SerialNumber, &d.DeviceType, &d.Status, &d.Model, &d.Vendor, &d.PurchaseDate, &d.CreatedAt, &d.UpdatedAt); err != nil {
            return nil, err
        }
        out = append(out, d)
    }
    return out, rows.Err()
}

func (r *Repo) UpdateDevice(ctx context.Context, d Device) error {
    res, err := r.db.ExecContext(ctx,
        `UPDATE devices SET site_id=$1, name=$2, serial_number=$3, device_type=$4, status=$5, model=$6, vendor=$7, purchase_date=$8, updated_at=NOW()
         WHERE id=$9`,
        d.SiteID, d.Name, d.SerialNumber, d.DeviceType, d.Status, d.Model, d.Vendor, d.PurchaseDate, d.ID)
    if err != nil {
        return err
    }
    n, _ := res.RowsAffected()
    if n == 0 {
        return ErrNotFound
    }
    return nil
}

func (r *Repo) DeleteDevice(ctx context.Context, id string) error {
    res, err := r.db.ExecContext(ctx, `DELETE FROM devices WHERE id=$1`, id)
    if err != nil {
        return err
    }
    n, _ := res.RowsAffected()
    if n == 0 {
        return ErrNotFound
    }
    return nil
}

// Combined read

func (r *Repo) GetSiteWithDevices(ctx context.Context, id string) (SiteWithDevices, error) {
    s, err := r.GetSite(ctx, id)
    if err != nil {
        return SiteWithDevices{}, err
    }
    devs, err := r.ListDevicesBySite(ctx, id)
    if err != nil {
        return SiteWithDevices{}, err
    }
    return SiteWithDevices{Site: s, Devices: devs}, nil
}
